\end{align*}
where $\|F\|_{MW^{m_z,m_o}_2(\mathcal{Z}\times \mathcal{O}; H)} := \sum_{|\boldsymbol\alpha|\leq m_z}\sum_{|\boldsymbol\beta|\leq m_o} \| D^{\boldsymbol\alpha}_{\mathbf z} D^{\boldsymbol\beta}_{\mathbf o} F \|_{L^2(\mathcal{Z}\times \mathcal{O}; H)}$.

\begin{align*}
