Let $\mathcal{X} = \prod_{i=1}^d \mathcal{X}^{(i)} \subseteq \mathbb{R}^d$ be a subset with non-empty interior, $\nu$ be a product measure on $\mathcal{X}$ with $\nu=\otimes_{i=1}^d \nu_i$, and $f: \mathcal{X} \rightarrow \mathbb{R}$ be a function in $L^p(\nu)$ for some $p \in (0, \infty]$. 
The $r$-th modulus of smoothness of $f$ is defined by
\begin{talign}\label{eq:module_smoothness}
    \omega_{r, p}\left(f, \boldsymbol{t}, \mathcal{X} \right) = \sup _{0<\left|h_i\right| \leq t_i} \left\|\triangle_{\boldsymbol{h}}^{r}f \right\|_{L^p\left(\nu\right)},
\end{talign}
where the $r$-th difference of $f$ in the direction $\boldsymbol{h}$ at point $\mathbf x$, denoted as $\triangle_{\boldsymbol{h}}^{r} f \left( \mathbf x \right)$, is defined through recursion: $\Delta_{\boldsymbol{h}}^0 f(\mathbf x) :=f(\mathbf x)$ and $\Delta_{\boldsymbol{h}}^r f(\mathbf x) :=\Delta_{\boldsymbol{h}}^{r-1} f(\mathbf x+\boldsymbol{h})-\Delta_{\boldsymbol{h}}^{r-1} f(\mathbf x)$ if $\mathbf x, \mathbf x+\boldsymbol{h}, \ldots, \mathbf x+r \boldsymbol{h} \in \mathcal{X}$ and $0$ otherwise.

\label{defi:abs}
For $p \in[1, \infty), q \in[1, \infty]$ and $\boldsymbol{s}=\left(s_1, \ldots, s_d\right) \in \mathbb{R}_{+}^d$, the anisotropic Besov space $B_{p, q}^{\boldsymbol{s}}(\nu)$ is defined by
\begin{talign}\label{eq:ani_besov_space}
    B_{p, q}^{\boldsymbol{s}}(\nu):=\left\{f \in L^p(\nu): \|f\|_{B_{p, q}^{\boldsymbol{s}}(\nu)} := \|f\|_{L^p(\nu)} + |f|_{B_{p, q}^{\boldsymbol{s}}\left(\nu\right)}<\infty\right\} ,
\end{talign}
where the Besov semi-norm $|f|_{B_{p, q}^{\boldsymbol{s}}\left(\nu\right)}$ is defined as, 
\begin{talign}\label{eq:besov_semi_norm}
|f|_{B_{p, q}^{\boldsymbol{s}}\left(\nu\right)} := \left[ \int_0^1\left[t^{-1} \omega_{r, p} \left(f, t^{1 / s_1}, \ldots, t^{1 / s_d}, \mathcal{X} \right)\right]^q \;\frac{\mathrm{d}t}{t}\right]^{1 / q},
\end{talign}
for $r = \max\{ \lfloor s_1 \rfloor, \ldots, \lfloor s_d \rfloor \} + 1$. When $q = \infty$, we replace the integral by a supremum in Eq. \eqref{eq:besov_semi_norm}. When $\nu$ is the Lebesgue measure over $\mathcal{X}$, we use the notation $B_{p, q}^{\boldsymbol{s}}(\mathcal{X}) := B_{p, q}^{\boldsymbol{s}}(\nu)$.

\end{aligned}
\end{talign}
where $\mathrm{supp}$ for an element of $L^2(\mathbb{R}^{d_x})$ is defined in \Cref{defi:fn_dist} and \Cref{defi:supp_dist} in the Supplementary.

