    \tau_J^{\mathrm{sieve}} := \sup_{0\neq f\in \Psi_J} \frac{\|f\|_{L^2(P_{X})}}{\|Tf\|_{L^2(P_{Z})}},
\end{align}
where $\Psi_J$ denotes the $J$th sieve space for the treatment variable \citep[Section 3]{Chen_2018}.

\begin{align}\label{eq:sieve_moip}
    \tau_J^{\mathrm{sieve}} := \sup_{0\neq f\in \Psi_J} \frac{\|f\|_{L^2(P_{X})}}{\|Tf\|_{L^2(P_{Z})}},
\end{align}

\begin{align}\label{eq:kernel_moip}
    \tau_{\gamma}^{\mathrm{Fourier}} := \sup_{0\neq f\in \mathrm{LF}(\gamma)\cap L^{\infty}(P_{XO})} \frac{\|f\|_{L^2(P_{X})}}{\|Tf\|_{L^2(P_{Z})}}. 
\end{align}

\label{rem:partial_smoothing}
Existing work that concerns NPIV-O in the literature circumvents the partial identity structure of $T$ either by imposing additional structural assumptions~\citep{blundell2007semi, syrgkanis2019machine} or by stratifying the problem on $O$~\citep{horowitz2011applied} thereby reducing NPIV-O to NPIV, which is statistically inefficient and scales poorly with the dimension of $O$. 
Instead of $T$, \citet[Section 3.3]{Chen_2018} consider the compactness and the smoothing effect of the \emph{partial} conditional expectation operator $T_{\mathbf o}: L^2(P_{X\mid O = \mathbf o})\to L^2(P_{Z\mid O=\mathbf o})$ for each $\mathbf o\in \mathcal{O} $. \citet[Section 3.3]{Chen_2018} proves that, if $\Psi_J$ (defined in the above remark) equals the span of the first $J$ eigenvectors of $T_{\mathbf o}^\ast T_{\mathbf o}$ for any $\mathbf o\in\mathcal{O}$, then
\begin{align}
\label{eq:chen_smoip_observed}
    \tau_J^{\mathrm{sieve}} \asymp \mathbb{E}_{\mathbf o\sim O}[\mu_{J, \mathbf o}^2]^{-\frac{1}{2}},
\end{align}
where $\mu_{J,\mathbf o}$ is the $J$th singular value of $T_{\mathbf o}$ arranged in non-increasing order. \citet{Chen_2018} then claims that the convergence rates derived for the standard NPIV can be extended to NPIV-O. However, we identify an essential oversight: \citet[Assumption 4 (ii)]{Chen_2018}, which is required for their $L^2$-norm upper bound, cannot hold in the NPIV-O setting. This assumption states that for $\Psi_J$, $f_{\ast}$ satisfies the following inequality:
\begin{align*}
    \tau_J^{\mathrm{sieve}}\|T(f_{\ast} - \Pi_J f_{\ast})\|_{L^2(P_{ZO})}\leq \|f_{\ast} - \Pi_{J}f_{\ast}\|_{L^2(P_{XO})},
\end{align*}
where $\Pi_J: L^2(P_{XO})\to \Psi_J$ denotes the $L^2$-orthogonal projection from $L^2(P_{XO})$ onto $\Psi_J$. 
In the NPIV-O setting, if $f_{\ast}$ depends only on $\mathbf o$ and $P_{XO}$ is the Lebesgue measure, then the projection $\Pi_J f_{\ast}$ also depends only on $\mathbf o$. 
This implies $(T^\ast T)(f_{\ast} - \Pi_J f_{\ast}) = f_{\ast} - \Pi_J f_{\ast}$ as per Eq.~\eqref{eq:TTast_mapping}, forcing ${\tau_J^{\mathrm{sieve}}}^{-1} = O(1)$, causing a contradiction with the measure of ill-posedness condition that $\tau_J^{\mathrm{sieve}} = \mathcal{O}(J^{\eta_0})$ unless $\eta_0 = 0$. 
\citet{HallHorowitz2005} addresses NPIV-O by assuming smoothness of $f_\ast(\cdot, \mathbf o)$ relative to $\mathcal{R}(T_\mathbf o^\ast T_\mathbf o)$ for each $\mathbf o\in\mathcal{O}$, which is hard to interpret because $T_\mathbf o$ is
unknown in NPIV-O.

\begin{align}
\label{eq:chen_smoip_observed}
    \tau_J^{\mathrm{sieve}} \asymp \mathbb{E}_{\mathbf o\sim O}[\mu_{J, \mathbf o}^2]^{-\frac{1}{2}},
\end{align}

\begin{align*}
    \tau_J^{\mathrm{sieve}}\|T(f_{\ast} - \Pi_J f_{\ast})\|_{L^2(P_{ZO})}\leq \|f_{\ast} - \Pi_{J}f_{\ast}\|_{L^2(P_{XO})},
\end{align*}

