We are going to apply \citet[Theorem 3]{JMLR:v25:23-1663} to obtain the desired result. To this end, we need to verify the assumptions (EVD) and (SRC) made in \cite{JMLR:v25:23-1663}. Note that we let the assumption (EMB) of \cite{JMLR:v25:23-1663} be trivially verified with $\alpha = 1$, as we prove in \Cref{prop:F_ast_sobolev} that $F_{\ast} \in [\mathcal{G}]^\beta$ with $\beta > 1$, therefore $\beta + p > 1 + p > 1 = \alpha$ falls in Case 2 of Theorem 3 of \cite{JMLR:v25:23-1663}. 

\vspace{3mm}
\noindent
\underline{\textit{Verification of (EVD)}}
Let $\phi_{Z}$ (resp. $\phi_{O}$) denote the feature map of $\mathcal{H}_{Z}$ (resp. $\mathcal{H}_{O}$). Define $C_{ZO}:\mathcal{H}_Z \otimes \mathcal{H}_O \to \mathcal{H}_Z \otimes \mathcal{H}_O$ as the covariance operator.
\begin{align*}
    C_{ZO} = \iint_{\mathcal{Z}\times\mathcal{O}} (\phi_Z(\mathbf z) \otimes \phi_O(\mathbf o)) \otimes (\phi_Z(\mathbf z) \otimes \phi_O(\mathbf o)) p_{ZO}(\mathbf z, \mathbf o) \;\mathrm{d}\mathbf z \;\mathrm{d}\mathbf o .
\end{align*}
We also define another two auxiliary covariance operators $\bar{C}_Z:\mathcal{H}_Z\to \mathcal{H}_Z$ and $\bar{C}_O:\mathcal{H}_O\to \mathcal{H}_O$.
\begin{align*}
    \bar{C}_Z = \int_\mathcal{Z} \phi_Z(\mathbf z) \otimes \phi_Z(\mathbf z) p_
    {Z}(\mathbf z)\;\mathrm{d}\mathbf z, \quad \bar{C}_O = \int_\mathcal{O} \phi_O(\mathbf o) \otimes \phi_O(\mathbf o)p_O(\mathbf o)\; \mathrm{d}\mathbf o .
\end{align*}
Since $k_Z$ and $k_O$ are bounded, $C_{ZO}, \bar{C}_Z, \bar{C}_O$ are all self-adjoint compact operators. 
From \cite{edmunds1996function} and \cite{fischer2020sobolev}[Section 4], we have $\lambda_i(\bar{C}_Z) \asymp i^{-2 t_z/d_z}$ and $\lambda_i(\bar{C}_O) \asymp i^{-2 t_o/d_o}$. 
We know from Assumption \ref{assn: technical} that $P_{ZO}$ is equivalent to the Lebesgue measure, so by Jensen's inequality, we have $C_{ZO} \leq \bar{C}_Z \otimes \bar{C}_O$, where $\otimes$ here denotes an operator tensor product. Hence, from Lemma 17 of \cite{meunier2024nonparametricinstrumentalregressionkernel} we have $\lambda_i(C_{ZO}) \leq \lambda_i(\bar{C}_Z \otimes \bar{C}_O)$. Finally, from \Cref{lem:tensor_evd} we have 
\begin{align*}
    \lambda_i(C_{ZO}) \leq \lambda_i(\bar{C}_Z \otimes \bar{C}_O) \lesssim i^{-2 t_z/d_z \wedge 2 t_o/d_o + \zeta}
\end{align*}
for any $\zeta > 0$.
Therefore, we have proved that (EVD) hold with $1/p = 2 t_z/d_z \wedge 2 t_o/d_o - \zeta$.
Hence, $p = d^{\dag}/2 + \zeta$ for any $\zeta > 0$.

\vspace{3mm}
\noindent
\underline{\textit{Verification of (SRC)}}
Let $\beta = m^{\dag}$. By the definition of vector-valued interpolation space in \cite{JMLR:v25:23-1663}[Definition 2] and the Assumption that $P_{ZO}$ is equivalent to the Lebesgue measure, we have that
\begin{align*}
    [\mathcal{G}]^{\beta} &\cong \mathcal{H}_{X,\gamma_x} \otimes [L^2(\mathcal{Z}\times\mathcal{O}), \mathcal{H}_Z \otimes \mathcal{H}_O]_{\beta, 2} \\
    &\stackrel{(a)}{\cong} \mathcal{H}_{X,\gamma_x} \otimes [L^2(\mathcal{Z}\times\mathcal{O}), W^{t_z}_2(\mathcal{Z}) \otimes W^{t_o}_2(\mathcal{O})]_{\beta, 2} \\
    &\stackrel{(b)}{\cong} \mathcal{H}_{X,\gamma_x} \otimes W^{t_z \beta}_2(\mathcal{Z}) \otimes W^{t_o \beta}_2(\mathcal{O})\\
    &\stackrel{(\ast)}{\supseteq} \mathcal{H}_{X,\gamma_x}\otimes W^{m_z}_2(\mathcal{Z}) \otimes W^{m_o}_2(\mathcal{O})\\
    &\stackrel{(c)}{\cong} \mathcal{H}_{X,\gamma_x}\otimes MW^{m_z,m_o}_{2}(\mathcal{Z}\times \mathcal{O};\mathbb{R})\\
    &\stackrel{(d)}{\cong} MW^{m_z,m_o}_{2}(\mathcal{Z}\times \mathcal{O};\mathcal{H}_{X,\gamma_x}).
\end{align*}
where in $(a)$ we use Corollary 10.13 and Theorem 10.46 of \cite{wendland2004scattered}, in $(b)$ we use \Cref{lem:tensor_interpolation}, in $(c)$ we use proposition 3.1 of \cite{SICKEL2009748}, which shows $MW^{m_z, m_o}_2(\mathcal{Z}\times\mathcal{O}) \cong W^{m_z}_2(\mathcal{Z}) \otimes W^{m_o}_2(\mathcal{O})$, and in $(d)$ we use \Cref{lem:vv_mss}. Furthermore, the inclusion in $(\ast)$ is a continuous embedding. We show in \Cref{prop:F_ast_sobolev} that under \Cref{assn: technical}, $\|F_{\ast}\|_{MW^{m_z,m_o}_{2}(\mathcal{Z}\times \mathcal{O};\mathcal{H}_{X,\gamma_x})}$ is bounded by a constant. Hence we deduce from the above embedding that 
