    \lambda \| f_\lambda\|_{\mathcal{H}_{\gamma_x,\gamma_o}}^2 + \left\|T\left(f_{\ast} - \left[f_{\lambda}\right]\right)\right\|_{L^2(P_{ZO})}^2 \leq C n^{-\frac{2(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}},
\end{align*}

Recall $f_{\mathrm{aux}}\in \mathcal{H}_{\gamma_x,\gamma_o}$ defined in Eq.~\eqref{eq:f_aux}. We write 
\begin{align*}
    f_{\mathrm{aux}} = f_{\ast} \ast K_{\gamma_o} - (f_{\ast} - f_{\ast , \mathrm{low}}) \ast K_{\gamma_o} + (f_{\ast} - f_{\ast, \mathrm{low}}) \ast K_{\gamma_o} \ast K_{\gamma_x}
.\end{align*}
By definition of $f_\lambda$, we have
\begin{align}
    &\quad \lambda \| f_\lambda\|_{\mathcal{H}_{\gamma_x,\gamma_o}}^2 + \left\|T\left(f_{\ast} - \left[f_{\lambda}\right]\right)\right\|_{L^2(P_{ZO})}^2 
    \nonumber \\
    &=\inf_{f\in \mathcal{H}_{\gamma_x,\gamma_o}}\lambda \|f\|_{\mathcal{H}_{\gamma_x,\gamma_o}}^2 + \left\|Tf_{\ast} - T[f]\right\|_{L^2(P_{ZO})}^2\nonumber \\
    &\leq \lambda \|f_{\mathrm{aux}}\|_{\mathcal{H}_{\gamma_x,\gamma_o}}^2 + \left\|Tf_{\ast} - T[f_{\mathrm{aux}}]\right\|_{L^2(P_{ZO})}^2 \nonumber \\
    &\leq \lambda \|f_{\mathrm{aux}} \|_{\mathcal{H}_{\gamma_x,\gamma_o}}^2 + \left\|Tf_{\ast} - T \left(f_{\ast} \ast K_{\gamma_o} \right)\right\|_{L^2(P_{ZO})}^2 \nonumber \\
    &+\left\| T\left((f_{\ast} - f_{\ast , \mathrm{low}}) \ast K_{\gamma_o} - (f_{\ast} - f_{\ast, \mathrm{low}}) \ast K_{\gamma_o} \ast K_{\gamma_x}\right) \right\|_{L^2(P_{ZO})}^2. \label{eq:proj_approx_error}
\end{align}
For the first term, we know from Eq.~\eqref{eq:f_aux_norm} and \Cref{ass:f_ast} in the main text that 
\begin{align*}
    \lambda\|f_{\mathrm{aux}}\|_{\mathcal{H}_{\gamma_x,\gamma_o}}^2 \leq n^{-1} \cdot 2 n^{\frac{1+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} \|f_\ast\|_{L^2(\mathbb{R}^{d_x+d_o})} \leq 2 n^{-\frac{2(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} .
\end{align*}
For the second term, we have
\begin{align*}
    \left\|Tf_{\ast} - T \left(f_{\ast} \ast K_{\gamma_o} \right)\right\|_{L^2(P_{ZO})}^2 &\leq \left\|f_{\ast} - f_{\ast} \ast K_{\gamma_o} \right\|_{L^2(P_{XO})}^2 \\
    &\lesssim \left\|f_{\ast} - f_{\ast} \ast K_{\gamma_o} \right\|_{L^2(\mathcal{X}\times\mathcal{O})}^2 \\
    &\lesssim |f_{\ast}|^2_{B^{s_x,s_o}_{2,q}(\mathbb{R}^{d_x+d_o})} \cdot \max\{0, \gamma_o^{2s_o}\}\\
    &= |f_{\ast}|^2_{B^{s_x,s_o}_{2,q}(\mathbb{R}^{d_x+d_o})}  n^{-\frac{2(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}.
\end{align*}
The first inequality above holds because $T$ is a bounded operator;
the second inequality holds by Assumption \ref{assn: technical} that $P_{XO}$ admits a bounded density. 
The second last inequality above holds by using \Cref{lem:hang_prop_3} for $\boldsymbol{\gamma} = (\underbrace{0,\dots, 0}_{d_x},\underbrace{\gamma_o,\dots,\gamma_o}_{d_o})$. 

\noindent
For the third term, we note that $(\forall \mathbf o\in \mathbb{R}^{d_o})$, 
\begin{align*}
    \mathcal{F}[\left((f_{\ast} - f_{\ast , \mathrm{low}}) \ast K_{\gamma_o} - (f_{\ast} - f_{\ast, \mathrm{low}}) \ast K_{\gamma_o} \ast K_{\gamma_x}\right)(\cdot, \mathbf o)] 
\end{align*}
is supported on the complement of $\{\mathbf x: \|\mathbf x\| \leq \gamma_x^{-1}\}$ (see~Eq. \eqref{eq:f_ast_low}). Thus it follows from \Cref{ass:T_contractivity} that
\begin{align*}
    &\quad \left\| T\left((f_{\ast} - f_{\ast , \mathrm{low}}) \ast K_{\gamma_o} - (f_{\ast} - f_{\ast, \mathrm{low}}) \ast K_{\gamma_o} \ast K_{\gamma_x}\right) \right\|_{L^2(P_{ZO})}^2 \\
    &\leq \gamma_x^{2d_x\eta_1}\left\| (f_{\ast} - f_{\ast , \mathrm{low}}) \ast K_{\gamma_o} - (f_{\ast} - f_{\ast, \mathrm{low}}) \ast K_{\gamma_o} \ast K_{\gamma_x} \right\|_{L^2(P_{XO})}^2\\
    &\stackrel{(i)}{\lesssim} \gamma_x^{2d_x\eta_1+ 2s_x}\cdot \left|(f_{\ast} - f_{\ast , \mathrm{low}}) \ast K_{\gamma_o}\right|^2_{B^{s_x,s_o}_{2,q}(\mathbb{R}^{d_x+d_o})}\\
    &\stackrel{(ii)}{\leq} \gamma_x^{2d_x\eta_1+ 2s_x}\cdot \left|f_{\ast} \ast K_{\gamma_o}\right|^2_{B^{s_x,s_o}_{2,q}(\mathbb{R}^{d_x+d_o})}\\
    &\stackrel{(iii)}{\leq} \gamma_x^{2d_x\eta_1+ 2s_x}\cdot \left|f_{\ast}\right|^2_{B^{s_x,s_o}_{2,q}(\mathbb{R}^{d_x+d_o})} \|K_{\gamma_o}\|^2_{L^1(\mathbb{R}^{d_o})}\\
    &\stackrel{(iv)}{\lesssim} n^{-\frac{2(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}. 
\end{align*}
In the above derivations, $(i)$ follows by using \Cref{lem:hang_prop_3} for $\boldsymbol{\gamma} = (\underbrace{\gamma_x,\dots,\gamma_x}_{d_x},\underbrace{0,\dots,0}_{d_o})$ and the Assumption that $P_{XO}$ admits a bounded density, $(ii)$ follows from the proof of \Cref{lem:new_besov_mask}, $(iii)$ follows from \Cref{lem:besov_young}, and $(iv)$ follows by the fact that $\|K_{\gamma_o}\|_{L^1(\mathbb{R})}= 1$ \citep[Section 4.1.2]{Giné_Nickl_2015} and \Cref{ass:f_ast} in the main text.

Combine the upper bound on the three terms in Eq.~\eqref{eq:proj_approx_error} and we obtain
\begin{align}\label{eq:lambda_f_lambda_T_L2}
    \lambda \| f_\lambda\|_{\mathcal{H}_{\gamma_x,\gamma_o}}^2 + \left\|T\left(f_{\ast} - \left[f_{\lambda}\right]\right)\right\|_{L^2(P_{ZO})}^2 \leq n^{-\frac{2(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}.
\end{align}
The proof concludes here.
In addition to that, from Eq.~\eqref{eq:proj_approx_error}, we also have
\begin{align}\label{eq:Tf_Tf_aux}
    \left\|Tf_{\ast} - T[f_{\mathrm{aux}}]\right\|_{L^2(P_{ZO})} \leq C n^{-\frac{\frac{s_x}{d_x}+\eta_1}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} .
\end{align}
Also, if we follow the same derivations as above, we obtain
\begin{align}\label{eq:f_f_aux_diff}
    \left\|f_{\ast} - [f_{\mathrm{aux}}] \right\|_{L^2(P_{XO})} \leq C n^{-\frac{\frac{s_x}{d_x}}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} .
\end{align}

