    f_{\mathrm{aux}} = f_{\ast} \ast K_{\gamma_o} - (f_{\ast} - f_{\ast , \mathrm{low}}) \ast K_{\gamma_o} + (f_{\ast} - f_{\ast, \mathrm{low}}) \ast K_{\gamma_o} \ast K_{\gamma_x}
.\end{align*}

\begin{align}
    &\quad \lambda \| f_\lambda\|_{\mathcal{H}_{\gamma_x,\gamma_o}}^2 + \left\|T\left(f_{\ast} - \left[f_{\lambda}\right]\right)\right\|_{L^2(P_{ZO})}^2 
    \nonumber \\
    &=\inf_{f\in \mathcal{H}_{\gamma_x,\gamma_o}}\lambda \|f\|_{\mathcal{H}_{\gamma_x,\gamma_o}}^2 + \left\|Tf_{\ast} - T[f]\right\|_{L^2(P_{ZO})}^2\nonumber \\
    &\leq \lambda \|f_{\mathrm{aux}}\|_{\mathcal{H}_{\gamma_x,\gamma_o}}^2 + \left\|Tf_{\ast} - T[f_{\mathrm{aux}}]\right\|_{L^2(P_{ZO})}^2 \nonumber \\
    &\leq \lambda \|f_{\mathrm{aux}} \|_{\mathcal{H}_{\gamma_x,\gamma_o}}^2 + \left\|Tf_{\ast} - T \left(f_{\ast} \ast K_{\gamma_o} \right)\right\|_{L^2(P_{ZO})}^2 \nonumber \\
    &+\left\| T\left((f_{\ast} - f_{\ast , \mathrm{low}}) \ast K_{\gamma_o} - (f_{\ast} - f_{\ast, \mathrm{low}}) \ast K_{\gamma_o} \ast K_{\gamma_x}\right) \right\|_{L^2(P_{ZO})}^2. \label{eq:proj_approx_error}
\end{align}

\begin{align*}
    \lambda\|f_{\mathrm{aux}}\|_{\mathcal{H}_{\gamma_x,\gamma_o}}^2 \leq n^{-1} \cdot 2 n^{\frac{1+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} \|f_\ast\|_{L^2(\mathbb{R}^{d_x+d_o})} \leq 2 n^{-\frac{2(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} .
\end{align*}

\begin{align*}
    \left\|Tf_{\ast} - T \left(f_{\ast} \ast K_{\gamma_o} \right)\right\|_{L^2(P_{ZO})}^2 &\leq \left\|f_{\ast} - f_{\ast} \ast K_{\gamma_o} \right\|_{L^2(P_{XO})}^2 \\
    &\lesssim \left\|f_{\ast} - f_{\ast} \ast K_{\gamma_o} \right\|_{L^2(\mathcal{X}\times\mathcal{O})}^2 \\
    &\lesssim |f_{\ast}|^2_{B^{s_x,s_o}_{2,q}(\mathbb{R}^{d_x+d_o})} \cdot \max\{0, \gamma_o^{2s_o}\}\\
    &= |f_{\ast}|^2_{B^{s_x,s_o}_{2,q}(\mathbb{R}^{d_x+d_o})}  n^{-\frac{2(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}.
\end{align*}

\begin{align*}
    \mathcal{F}[\left((f_{\ast} - f_{\ast , \mathrm{low}}) \ast K_{\gamma_o} - (f_{\ast} - f_{\ast, \mathrm{low}}) \ast K_{\gamma_o} \ast K_{\gamma_x}\right)(\cdot, \mathbf o)] 
\end{align*}

\begin{align}\label{eq:lambda_f_lambda_T_L2}
    \lambda \| f_\lambda\|_{\mathcal{H}_{\gamma_x,\gamma_o}}^2 + \left\|T\left(f_{\ast} - \left[f_{\lambda}\right]\right)\right\|_{L^2(P_{ZO})}^2 \leq n^{-\frac{2(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}.
\end{align}

\begin{align}\label{eq:Tf_Tf_aux}
    \left\|Tf_{\ast} - T[f_{\mathrm{aux}}]\right\|_{L^2(P_{ZO})} \leq C n^{-\frac{\frac{s_x}{d_x}+\eta_1}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} .
\end{align}

\begin{align}\label{eq:f_f_aux_diff}
    \left\|f_{\ast} - [f_{\mathrm{aux}}] \right\|_{L^2(P_{XO})} \leq C n^{-\frac{\frac{s_x}{d_x}}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} .
\end{align}

\label{prop: projected_est_error}
Suppose Assumptions~\ref{assn: technical}, \ref{ass:f_ast}, \ref{ass:T_injective}, \ref{ass:T_frequency_ill_posedness} and \ref{ass:T_contractivity} in the main text hold. 
Let $\lambda \asymp n^{-1}$ and 
\begin{align*}
    \gamma_x = n^{-\frac{\frac{1}{d_x}}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}, \quad \gamma_o = n^{-\frac{\frac{1}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}. 
\end{align*} With $P^n$-probability $\geq 1-  4e^{-\tau}$, for sufficiently large $n\geq 1$, we have
\begin{align*}
\left\|T\left(\left[\bar{f}_{\lambda}\right] - [f_{\lambda}]]\right)\right\|_{L^2(P_{ZO})}^2 \leq C \tau^2 n^{-\frac{2(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} (\log n)^{d_x+d_o+1},
\end{align*}
for some constant $C$ independent of $n$.

\begin{align*}
    \gamma_x = n^{-\frac{\frac{1}{d_x}}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}, \quad \gamma_o = n^{-\frac{\frac{1}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}. 
\end{align*}

\begin{align*}
\left\|T\left(\left[\bar{f}_{\lambda}\right] - [f_{\lambda}]]\right)\right\|_{L^2(P_{ZO})}^2 \leq C \tau^2 n^{-\frac{2(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} (\log n)^{d_x+d_o+1},
\end{align*}

Recall the definition of $\bar{h}_{\lambda}$ defined in Eq.~\eqref{eq:hat_bhl_bvfl} and $h_\lambda$ defined in Eq.~\eqref{eq:bhl_bvfl}.
\begin{align*}
    \bar{h}_{\lambda} &= arg\,min_{h\in \mathcal{H}_{FO}}\lambda \|h\|_{\mathcal{H}_{FO}}^2 + \frac{1}{n}\sum_{i=1}^{n}(h(\mathbf z_i,\mathbf o_i) - y_i)^2 . \\
    h_{\lambda} &= arg\,min_{h\in\mathcal{H}_{FO}}\lambda \|h\|^2_{\mathcal{H}_{FO}} + \|h_{\ast} - h\|^2_{L^2(P_{ZO})}.
\end{align*} 
Recall that we have proved that $\|T([\bar{f}_{\lambda}] - [f_{\lambda}])\|_{L^2(P_{ZO})} = \|[\bar{h}_{\lambda}] - [h_{\lambda}] \|_{L^2(P_{ZO})}$ in Eq.~\eqref{eq:error_translate}, so the proof of \Cref{prop: projected_est_error} is translated to the estimation error of a standard kernel ridge regression with hypothesis space $\mathcal{H}_{FO}$ and the target function $h_\ast := T f_\ast \in L^2(P_{ZO})$. Next, we are going to apply existing results, mainly Theorem 16 of \cite{fischer2020sobolev}, to our setting.

From Eq. \eqref{eq:error_translate} and \cite{fischer2020sobolev}[Lemma 12], we have
\begin{align}
\label{eq:prop_first_line_TFF}
     \left\| [\bar{h}_{\lambda}] - [h_{\lambda}]\right\|_{L^2(P_{ZO})} \leq \left\|C_{FO}^{\frac{1}{2}}\left(\bar{h}_{\lambda} - h_{\lambda}\right)\right\|_{\mathcal{H}_{FO}} =: (\ast)
\end{align}
Next, we will upper bound $(\ast)$ using Theorem 16 from \citet{fischer2020sobolev}. To apply this result, we must verify the underlying assumptions and control the auxiliary quantities specified in Theorem 16 from \citet{fischer2020sobolev}. 

First, we are going to verify the (MOM) condition.
By \Cref{ass:subgaussian}, we know that
\begin{align*}
    \int_{\mathbb{R}}\left|y- (T f_\ast)(\mathbf z, \mathbf o)\right|^m p(y \mid \mathbf z, \mathbf o)dy &= \mathbb{E}\left[|\upsilon|^m\mid Z=\mathbf z,O=\mathbf o\right] \\
    &\leq (\sqrt{2}C\sigma)^m(m/2)^{\frac{m}{2}} \leq \frac{1}{2}(2C\sigma)^mm! 
\end{align*}
by \citet[Eq. (2.15)]{vershynin2018high}, for some universal constant $C>0$. Hence the (MOM) condition of \cite{fischer2020sobolev} is satisfied.

Next, we control the auxiliary quantities in \cite{fischer2020sobolev}[Theorem 16]. Recall $m_z,m_o$ as defined in Eq. \eqref{def:m_z,m_o}. By definition, they satisfy
\begin{align*}
    \frac{d_o}{2m_o}<\frac{1 + 2\left(\frac{s_x}{d_x}+\eta_1\right)}{1+2\left(\frac{s_x}{d_x}+\eta_1\right) + \frac{d_o}{s_o}\left(\frac{s_x}{d_x}+\eta_1\right)}<1 , \quad \frac{d_z}{2m_z}\leq \frac{d_o}{2m_o} < 1 .
\end{align*}
Rearranging, we deduce that
\begin{align*}
    \frac{d_o}{2m_o} &< \left( 2m_o\frac{\frac{1}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)} + 1\right)^{-1}\\ \frac{d_o}{2m_o} &< \frac{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}{1+2(\frac{s_x}{d_x}+\eta_1)+\frac{2m_o+d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}.
\end{align*}
Hence there exists $\theta\in (0,1)$ such that the following inequalities hold simultaneously
\begin{align}\label{eq:theta_cond}
\begin{aligned}
    \frac{d_o}{2m_o\theta} < 1, \quad \frac{d_z}{2m_z\theta} < 1 \\
    \theta \leq \frac{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}{1+2(\frac{s_x}{d_x}+\eta_1)+\frac{2m_o+d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}\\
    \theta\left( 2m_o\frac{\frac{1}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)} + 1\right) < 1
\end{aligned}
\end{align}
Next, we define 
\begin{align}\label{eq:FS_thm_16_const}
\begin{aligned}
    g_{\lambda}&:= \log\left(2e\mathcal{N}_{FO}(\lambda)\frac{\|C_{FO}\|+\lambda}{\|C_{FO}\|}\right)\\
    A_{\lambda,\tau}&:= 8\left\|k^{\theta}_{FO}\right\|_{\infty}^2\tau g_{\lambda}\lambda^{-\theta}\\
    L_{\lambda}&:=\max\left\{L, \left\|h_{\ast} - [h_{\lambda}]\right\|_{L^{\infty}(P_{ZO})}\right\}
\end{aligned}
\end{align}

\textit{Controlling $g_{\lambda}$ and $A_{\lambda,\tau}$:  } 
From \Cref{prop:eff_dim}, we know that
\begin{align*}
    \mathcal{N}_{FO}(\lambda) \lesssim (\log n)^{d_x+d_o+1} \left(\gamma_x^{d_x}\gamma_o^{d_o}\right)^{-1} = (\log n)^{d_x+d_o+1} n^{\frac{1+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} .
\end{align*}
From \Cref{lem: C_f_op_norm_lower_bound}, we know that
\begin{align*}
    \|C_{FO}\| \geq a_f^{-1}\left(\frac{\sqrt{\pi}}{4}\right)^{\frac{d_x+d_o}{2}} n^{-\frac{1}{2}\frac{1+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} .
\end{align*}
Therefore, since $\lambda \asymp n^{-1}$, we have
\begin{align*}
    g_{\lambda } &= \log\left(2e\mathcal{N}_{FO}(\lambda) \left(1 + \lambda \|C_{FO}\|^{-1} \right) \right) \\
    &\lesssim \log\left((\log n)^{d_x+d_o+1} n^{\frac{1+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} \left(1 + n^{-1} \cdot n^{\frac{1}{2}\frac{1+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)} }\right)\right)\\
    &\leq \log\left(2(\log n)^{d_x+d_o+1} n^{\frac{1+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} \right)\\
    &= (d_x + d_o + 1)\log(\log n) + \frac{1+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)} \log(n)\\
    &\leq 2\frac{1+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}\log(n).
\end{align*}
The last step holds because $\log(n)$ dominates a constant term and $\log(\log n)$ for sufficiently large $n$. Since $\frac{d_o}{2m_o\theta}<1, \frac{d_z}{2m_z\theta}<1$, by \Cref{prop:emb_main}, we have
\begin{align}
    \left\|k_{FO}^{\theta}\right\|_{\infty} \lesssim \rho^{\theta}\gamma_o^{-\theta m_o}\label{eq: kfo_bound}.
\end{align}
Therefore, 
\begin{align}\label{eq:n_large_than_A}
    A_{\lambda,\tau} &\lesssim \left\|k_{FO}^{\theta}\right\|_{\infty}^2\tau \log(n)n^{\theta} \lesssim \gamma_o^{-2m_o\theta}\tau \log(n)n^{\theta} = \tau \log(n) n^{\theta\left( 2m_o\frac{\frac{1}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)} + 1\right)}.
\end{align}
Since $\theta ( 2m_o\frac{\frac{1}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)} + 1) < 1$ from Eq.~\eqref{eq:theta_cond}, $n>  A_{\lambda,\tau}$ holds for sufficiently large $n \geq 1$. 

\textit{Controlling $L_{\lambda}$:  } 
By Eq. \eqref{eq:lambda_f_lambda_T_L2}, we have
\begin{align*}
    \lambda \|f_{\lambda}\|^2_{\mathcal{H}_{\gamma_x,\gamma_o}} \leq n^{-\frac{2(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} \|f_\ast\|_{B^{s_x,s_o}_{2,q}(\mathbb{R}^{d_x+d_o})}^2 .
\end{align*}
Thus 
\begin{align}
\label{eq:f_lambda_hnorm_bound}
    \|f_{\lambda}\|^2_{\mathcal{H}_{\gamma_x,\gamma_o}} \leq n^{\frac{1+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} \|f_\ast\|_{B^{s_x,s_o}_{2,q} (\mathbb{R}^{d_x+d_o})}^2 .
\end{align}
Thus we have
\begin{align}
    L_{\lambda} &= \max\left\{2C\sigma, \|T(f_{\ast} - [f_{\lambda}])\|_{L^{\infty}(\mathcal{Z}\times \mathcal{O})}\right\}\nonumber\\
    &\leq \max\left\{2C\sigma, \|f_{\ast} - [f_{\lambda}]\|_{L^{\infty}(\mathcal{X}\times \mathcal{O})}\right\}\nonumber\\
    &\leq  \max\left\{2C\sigma, \|f_{\ast}\|_{L^{\infty}(\mathcal{X}\times \mathcal{O})} + \|[f_{\lambda}]\|_{L^{\infty}(\mathcal{X}\times \mathcal{O})}\right\}\nonumber\\
    &\stackrel{(i)}{\leq} \max\left\{2C\sigma, \|f_{\ast}\|_{L^{\infty}(\mathcal{X}\times \mathcal{O})} + \|f_{\lambda}\|_{\mathcal{H}_{\gamma_x,\gamma_o}}\right\}\nonumber\\
    &\stackrel{(ii)}{\leq} \max\left\{2C\sigma, \|f_{\ast}\|_{L^{\infty}(\mathcal{X}\times \mathcal{O})} + n^{\frac{1}{2}\frac{1+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} \|f_\ast\|_{B^{s_x,s_o}_{2,q} (\mathbb{R}^{d_x+d_o})} \right\}\nonumber\\
    &\stackrel{(iii)}{\leq} 2 n^{\frac{1}{2}\frac{1+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} \|f_\ast\|_{B^{s_x,s_o}_{2,q} (\mathbb{R}^{d_x+d_o})} \label{eq:l_lambda_bound},
\end{align}
