    &\stackrel{(b)}{\leq} \int_{\mathbb{R}^{d_x}} \|(f\ast \mathcal{F}^{-1}[\iota_{x,\gamma_x^{-1}}])(\mathbf x,\cdot)\|^2_{L^2(\mathbb{R}^{d_o})} \|K_{\gamma_o}\|^2_{L^1(\mathbb{R}^{d_o})}\\
    & = \|f\ast \mathcal{F}^{-1}[\iota_{x,\gamma_x^{-1}}]\|^2_{L^2(\mathbb{R}^{d_x+d_o})}.
\end{align*}
where in $(a)$, $(f\ast \mathcal{F}^{-1}[\iota_{x,\gamma_x^{-1}}])(\mathbf x,\cdot)$ is a slice function of any representative of $f\ast \mathcal{F}^{-1}[\iota_{x,\gamma_x^{-1}}]\in L^2(\mathbb{R}^{d_x})$, and $(b)$ follows from Young's Convolution Inequality. Hence we can apply $\mathcal{F}$ to $f\ast \mathcal{F}^{-1}[\iota_{x,\gamma_x^{-1}}]\in L^2(\mathbb{R}^{d_x+d_o})$ and we find 
\begin{align*}
    \mathcal{F}\left[\mathcal{F}_x^{-1}[\iota_{x,\gamma_x^{-1}}] \ast K_{\gamma_o} \ast f\right] = (\iota_{x,\gamma_x^{-1}}\otimes \mathcal{F}_o[K_{\gamma_o}]) \cdot \mathcal{F}[f].
\end{align*}
For $\phi(\mathbf x,\mathbf o) = \exp(- \gamma_x^{-2} \|\mathbf x\|_2^2) \cdot \exp(- \gamma_o^{-2} \|\mathbf o\|_2^2)$, its Fourier transform is 
\begin{align*}
    \mathcal{F}[\phi](\boldsymbol{\omega}_x,\boldsymbol{\omega}_o) = \pi^{d_x/2+d_o/2} \gamma_x^{d_x} \exp\left(-\frac{1}{4} \gamma_x^{2} \|\boldsymbol{\omega}_x\|_2^2\right) \cdot \gamma_o^{d_o}\exp\left(-\frac{1}{4} \gamma_o^{2} \|\boldsymbol{\omega}_o\|_2^2\right).
\end{align*}
Hence, by definition of Gaussian RKHS norm~\citep[Theorem 10.12]{wendland2004scattered}, 
\begin{align*}
    &\quad \left\| \mathcal{F}_x^{-1}[\iota_{x,\gamma_x^{-1}}]\ast K_{\gamma_o} \ast f\right\|_{\mathcal{H}_{\gamma_x,\gamma_o}}^2 \\
    &= \int_{\mathbb{R}^{d_x+d_o}} \frac{\left(\iota_{x,\gamma_x^{-1}}(\boldsymbol{\omega}_x) \cdot \mathcal{F}[f](\boldsymbol{\omega}_x,\boldsymbol{\omega}_o) \cdot \mathcal{F}_o[K_{\gamma_o}](\boldsymbol{\omega}_o)\right)^2}{\pi^{d_x/2+d_o/2} \gamma_x^{d_x} \exp\left(-\frac{1}{4} \gamma_x^{2} \|\boldsymbol{\omega}_x\|_2^2\right) \cdot \gamma_o^{d_o}\exp(-\frac{1}{4} \gamma_o^{2} \|\boldsymbol{\omega}_o\|_2^2)} \;\mathrm{d}\boldsymbol{\omega}_x \;\mathrm{d}\boldsymbol{\omega}_o \\
