Define the following sets 
\begin{align*}
    I_{\mathbf x} &:= \left\{\boldsymbol{\omega}_{x}\in\mathbb{R}^{d_x}: \|\boldsymbol{\omega}_x\|_2^2 \gamma_x^{2} (\log (\gamma_x^{-\delta_x}))^{-1} \leq 1 \right\}\\ \quad I_{\mathbf o} &:= \left\{\boldsymbol{\omega}_{o}\in\mathbb{R}^{d_o}: \|\boldsymbol{\omega}_{o}\|^2_{2}\gamma_o^{2} (\log (\gamma_o^{-\delta_o}))^{-1} \leq 1\right\}\\ I &:= I_{\mathbf x} \times I_{\mathbf o}\\
    \tilde{I} &:= \left\{(\boldsymbol{\omega}_x,\boldsymbol{\omega}_o)\in\mathbb{R}^{d_x+d_o}: \|\boldsymbol{\omega}_x\|_2^2 \gamma_x^{2} (\log (\gamma_x^{-\delta_x}))^{-1} + \|\boldsymbol{\omega}_{o}\|^2\gamma_o^{2} (\log (\gamma_o^{-\delta_o}))^{-1} \leq 1 \right\} .
\end{align*}
Note that $\tilde{I}\subset I$. Let $\iota_{x} : \mathbb{R}^{d_x}\to \{0,1\}$ denote the indicator function on $I_{\mathbf x}$, let $\iota_{o} : \mathbb{R}^{d_o}\to \{0,1\}$ denote the indicator function on $I_{\mathbf o}$, let $\iota:  \mathbb{R}^{d_x+d_o}\to \{0,1\}$ denote the indicator function on $I$, which satisfies $\iota = \iota_{x} \cdot \iota_{o}$. 
Thus we have
\begin{small}
\begin{align}
    &\quad \|f\|_{L^2(P_{XO})} \nonumber \\
    &\leq \left\|f\ast \mathcal{F}^{-1}(\iota)\right\|_{L^2(P_{XO})} + \left\|f\ast \mathcal{F}^{-1}(\iota) - f\right\|_{L^2(P_{XO})} \nonumber \\
    &\stackrel{(i)}{\leq} \gamma_x^{-d_x\eta_0} (\log (\gamma_x^{-\delta_x}))^{\frac{d_x\eta_0}{2}} \|T(f\ast \mathcal{F}^{-1}(\iota))\|_{L^2(P_{ZO})} + \left\|f\ast \mathcal{F}^{-1}(\iota) - f\right\|_{L^2(P_{XO})} \nonumber\\
    &\stackrel{(ii)}{\leq} \gamma_x^{-d_x\eta_0} (\log (\gamma_x^{-\delta_x}))^{\frac{d_x\eta_0}{2}} \|Tf\|_{L^2(P_{ZO})} \nonumber \\
    &\qquad + \left(1 + \gamma_x^{-d_x\eta_0} (\log (\gamma_x^{-\delta_x}))^{\frac{d_x\eta_0}{2}} \right)\left\|f\ast \mathcal{F}^{-1}(\iota) - f\right\|_{L^2(P_{XO})} 
    \nonumber \\
    &\lesssim \gamma_x^{-d_x\eta_0} (\log (\gamma_x^{-\delta_x}))^{\frac{d_x\eta_0}{2}} \|Tf\|_{L^2(P_{ZO})}  + \gamma_x^{-d_x\eta_0} (\log (\gamma_x^{-\delta_x}))^{\frac{d_x\eta_0}{2}} \left\|f\ast \mathcal{F}^{-1}(\iota) - f\right\|_{L^2(\mathcal{X}\times\mathcal{O})} 
    \label{eq:intermediate_reverse_link}.
\end{align}
\end{small}
In the above derivations,
\begin{itemize}
    \item $(i)$ follows from \Cref{ass:T_frequency_ill_posedness}, and for $\mathcal{F}_x,\mathcal{F}_o$ defined in the proof of \Cref{lem:mixed_convolution},
\begin{align*}
    (\forall \mathbf o\in \mathcal{O}),\; \mathrm{supp}(\mathcal{F}_x[(f\ast \mathcal{F}^{-1}(\iota))(\cdot,\mathbf o)]) = \mathrm{supp}(\mathcal{F}_x[(f\ast \mathcal{F}_o^{-1}[\iota_o])(\cdot, \mathbf o)] \cdot  \iota_x) \subseteq I_{\mathbf x},
\end{align*}
where we note that the relevant Fourier transforms exist since $f\in \mathcal{H}_{\gamma_x,\gamma_o}\subset L^2(\mathbb{R}^{d_x+d_o})$. 
    \item $(ii)$ follows from a triangular inequality and a Jensen's inequality. 
\end{itemize}
Next, we bound $(\ast) =\|f\ast \mathcal{F}^{-1}(\iota) - f\|_{L^2([0,1]^{d_x+d_o})}$. We have
\begin{align*}
    (\ast) &= \left\|f\ast \mathcal{F}^{-1}(\iota) - f\right\|_{L^2([0,1]^{d_x+d_o})} \leq \left\|f\ast \mathcal{F}^{-1}(\iota) - f\right\|_{L^2(\mathbb{R}^{d_x+d_o})}\\ &\stackrel{(a)}{=} \left\|\mathcal{F}\left[f\ast \mathcal{F}^{-1}(\iota) - f\right]\right\|_{L^2(\mathbb{R}^{d_x+d_o})}= \|\mathcal{F}[f]\iota - \mathcal{F}[f]\|_{L^2(\mathbb{R}^{d_x+d_o})}\\ &= \left(\int_{I^{c}} |\mathcal{F}[f](\boldsymbol{\omega})|^2\;\mathrm{d}\boldsymbol{\omega}\right)^{\frac{1}{2}} \stackrel{(b)}{\leq} \left(\int_{\tilde{I}^{c}} |\mathcal{F}[f](\boldsymbol{\omega})|^2\;\mathrm{d}\boldsymbol{\omega}\right)^{\frac{1}{2}} ,
\end{align*}
where $(a)$ holds by Plancherel's Theorem, $(b)$ holds by $\tilde{I}\subseteq I$. 
Recall that for $\mathbf{a}, \mathbf{b}\in\mathbb{R}^d$, $\mathbf{a} \odot \mathbf{b} := (a_1 b_1, \ldots, a_d b_d) \in \mathbb{R}^{d}$. For $\boldsymbol{\omega}=(\boldsymbol{\omega}_x, \boldsymbol{\omega}_o)$, we proceed from above to have,
\begin{small}
\begin{align*}
    &\leq \left(\int_{\tilde{I}^{c}} |\mathcal{F}[f](\boldsymbol{\omega})|^2 \exp\left(\frac{\|(\boldsymbol{\omega}_x \odot \boldsymbol{\gamma}_x, \boldsymbol{\omega}_o \odot \boldsymbol{\gamma}_o )\|^2_{2}}{4}\right)\exp\left(-\frac{\|(\boldsymbol{\omega}_x \odot \boldsymbol{\gamma}_x, \boldsymbol{\omega}_o \odot \boldsymbol{\gamma}_o ) \|^2_{2}}{4}\right)\;\mathrm{d}\boldsymbol{\omega}\right)^{\frac{1}{2}}\\
    &\leq \sup_{\boldsymbol{\omega}\in \tilde{I}^{c}}\exp\left(-\frac{\|(\boldsymbol{\omega}_x \odot \boldsymbol{\gamma}_x, \boldsymbol{\omega}_o \odot \boldsymbol{\gamma}_o )\|^2_{2}}{8}\right)\left(\int_{\mathbb{R}^{d_x+d_o}} |\mathcal{F}[f](\boldsymbol{\omega})|^2 \exp\left(\frac{\|(\boldsymbol{\omega}_x \odot \boldsymbol{\gamma}_x, \boldsymbol{\omega}_o \odot \boldsymbol{\gamma}_o ) \|^2_{2}}{4}\right)\;\mathrm{d}\boldsymbol{\omega}\right)^{\frac{1}{2}}\\
    &\stackrel{(c)}{\leq} \sup_{\boldsymbol{\omega}\in \tilde{I}^{c}}\exp\left(-\frac{\|(\boldsymbol{\omega}_x \odot \boldsymbol{\gamma}_x, \boldsymbol{\omega}_o \odot \boldsymbol{\gamma}_o ) \|^2_{2}}{8}\right)\left( \|f\|_{\mathcal{H}_{XO,\boldsymbol{\gamma}_x,\boldsymbol{\gamma}_o}}^2 2^{-\frac{d_x+d_o}{2}} \gamma_x^{d_x}\gamma_o^{d_o}\right)^{\frac{1}{2}}\\
    &\lesssim \sup_{\|\boldsymbol{\omega}_x\|_2^2 \gamma_x^{2} (\log (\gamma_x^{-\delta_x}))^{-1} + \|\boldsymbol{\omega}_{o}\|^2\gamma_o^{2} (\log (\gamma_o^{-\delta_o}))^{-1} \geq 1} \exp\left(-\frac{ \gamma_x^2 \|\boldsymbol{\omega}_x\|_2^2 + \gamma_o^2 \|\boldsymbol{\omega}_o\|_2^2 }{8}\right)\left(n  \gamma_x^{d_x}\gamma_o^{d_o}\right)^{\frac{1}{2}} \\
    &\leq \exp\left(-\frac{1}{8} \log(\gamma_x^{-\delta_x} ) \right)\left(n \gamma_x^{d_x} \gamma_o^{d_o}\right)^{\frac{1}{2}} \\
    &\asymp \gamma_x^{\frac{1}{8} \delta_x} \left(n \gamma_x^{d_x}\gamma_o^{d_o} \right)^{1/2},
\end{align*}
\end{small}
where $(c)$ holds by Lemma~\ref{lem:unit_ball_grkhs}.
Now we have proved the first claim of this lemma. Next, we proceed to prove the second claim by plugging in the specific values of $\delta_x,\delta_o$ and $\gamma_x,\gamma_o$. 
