    The NPIR-O model is more informative than the NPIV-O model in the sense that for each estimator $\hat{f}_n$ for the NPIV-O model, there is an estimator $\tilde{f}_n$ for the NPIR-O model with 
    \begin{align*}
        \sup_{(P_{ZO}, \sigma(\cdot, \cdot), f)\in \mathcal{C}_0}\mathbb{E}_{(P_{ZO},\sigma(\cdot, \cdot), f)}[\|\tilde{f}_n - f\|^2_{L^2(P_{XO})}] \leq \sup_{(P_{\epsilon ZXO}, f)\in \mathcal{C}}\mathbb{E}_{(P_{\epsilon ZXO, f})}[\|\hat{f}_n - f\|^2_{L^2(P_{XO})}].
    \end{align*}

\begin{align*}
        \sup_{(P_{ZO}, \sigma(\cdot, \cdot), f)\in \mathcal{C}_0}\mathbb{E}_{(P_{ZO},\sigma(\cdot, \cdot), f)}[\|\tilde{f}_n - f\|^2_{L^2(P_{XO})}] \leq \sup_{(P_{\epsilon ZXO}, f)\in \mathcal{C}}\mathbb{E}_{(P_{\epsilon ZXO, f})}[\|\hat{f}_n - f\|^2_{L^2(P_{XO})}].
    \end{align*}

\begin{align}
\label{eq:Bspline_main}
    M_{\mathfrak{K}, \boldsymbol{-\frac{\mathfrak{m}}{2}}}(\mathbf x) := \prod_{i=1}^{d_x}\iota_\mathfrak{m}\left(2^{\left\lfloor \mathfrak{K}\frac{\underline{s}}{s_x}\right\rfloor}x_i + \frac{\mathfrak{m}}{2} \right), \quad M_{\mathfrak{K},{\boldsymbol\ell}_o}(\mathbf o) := \prod_{j=1}^{d_o}\iota_\mathfrak{m}\left(2^{\left\lfloor \mathfrak{K}\frac{\underline{s}}{s_o}\right\rfloor}o_i - \ell_{o,j}\right).
\end{align}

\begin{align}\label{eq:calL}
    \mathcal{L} := \left\{({\boldsymbol\ell}_x,{\boldsymbol\ell}_o): {\boldsymbol\ell}_x \in \left\{0,1,\dots, \left\lfloor \frac{0.8\pi}{\zeta}2^{\frac{\mathfrak{K}\underline{s}}{s_x}}\right\rfloor\right\}^{d_x},  {\boldsymbol\ell}_o \in \left(m\mathbb{Z}\cap \left\{1, \dots, 2^{\left\lfloor \mathfrak{K}\frac{\underline{s}}{s_o}\right\rfloor}\right\}\right)^{d_o}\right\},
\end{align}

\begin{align}\label{eq:size_L}
