\end{align}

\begin{align}\label{eq:p_X_bump}
        p_X(\mathbf x)\propto \prod_{i=1}^{d_x} g(x_i), \quad g(x_i) := \exp\left(-\frac{2}{1 - 4x_i^2}\right) \mathbbm{1}_{x_i \in [-1/2, 1/2]} .
