\begin{align}
    \mathcal{F}[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}](\boldsymbol{\omega}_x) &= 2^{-\mathfrak{K}\frac{\underline{s}d_x}{s_x}}\mathcal{F}\left[M_{0,\boldsymbol{-\frac{\mathfrak{m}}{2}}}\ast \mathcal{F}^{-1}[\mathbbm{1}_{{\boldsymbol\ell}_{x}}]\right]\left(2^{-\frac{\mathfrak{K}\underline{s}}{s_x}}\boldsymbol{\omega}_x\right) \nonumber\\
    &= 2^{-\mathfrak{K}\frac{\underline{s}d_x}{s_x}} \cdot \mathcal{F}\left[M_{0,\boldsymbol{-\frac{\mathfrak{m}}{2}}}\right] \left(2^{-\frac{\mathfrak{K}\underline{s}}{s_x}}\boldsymbol{\omega}_x\right)  \cdot \mathbbm{1}_{{\boldsymbol\ell}_x}\left(2^{-\frac{\mathfrak{K}\underline{s}}{s_x}}\boldsymbol{\omega}_x\right) \nonumber \\
    &= \mathcal{F}\left[M_{\mathfrak{K},\boldsymbol{-\frac{\mathfrak{m}}{2}}}\right] \left(\boldsymbol{\omega}_x\right)  \cdot \mathbbm{1}_{{\boldsymbol\ell}_x}\left(2^{-\frac{\mathfrak{K}\underline{s}}{s_x}}\boldsymbol{\omega}_x\right)
