\begin{align}
    &\left\|\sum_{{\boldsymbol\ell}_x,{\boldsymbol\ell}_o} \alpha_{\mathbf v({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)}\Omega_{\mathfrak{K}({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)}\right\|^2_{L^2(P_{XO})}\nonumber\\
    =& \int_{[0,1]^{d_o}}\int_{\mathbb{R}^{d_x}}\sum_{\substack{{\boldsymbol\ell}_x,{\boldsymbol\ell}_o\nonumber\\ \Tilde{{\boldsymbol\ell}}_x, \Tilde{{\boldsymbol\ell}_o}}} \alpha_{\mathbf v({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)}\alpha_{\mathbf v(\Tilde{{\boldsymbol\ell}_x}, \Tilde{{\boldsymbol\ell}}_o)} \Omega_{\mathfrak{K},{\boldsymbol\ell}_x}(\mathbf x)\Omega_{k\Tilde{{\boldsymbol\ell}}_x}(\mathbf x)M_{\mathfrak{K},{\boldsymbol\ell}_o}(\mathbf o)M_{k\Tilde{{\boldsymbol\ell}}_o}(\mathbf o)p_X(\mathbf x)\;\mathrm{d}\mathbf x\;\mathrm{d}\mathbf o\nonumber\\
    = & \int_{\mathbb{R}^{d_x}}\sum_{\substack{{\boldsymbol\ell}_x,{\boldsymbol\ell}_o\\ \Tilde{{\boldsymbol\ell}}_x, \Tilde{{\boldsymbol\ell}_o}}} \alpha_{\mathbf v({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)}\alpha_{\mathbf v(\Tilde{{\boldsymbol\ell}_x}, \Tilde{{\boldsymbol\ell}}_o)} \Omega_{\mathfrak{K},{\boldsymbol\ell}_x}(\mathbf x)\Omega_{k\Tilde{{\boldsymbol\ell}}_x}(\mathbf x) p_X(\mathbf x)\left(\int_{[0,1]^{d_o}}M_{\mathfrak{K},{\boldsymbol\ell}_o}(\mathbf o)M_{k\Tilde{{\boldsymbol\ell}}_o}(\mathbf o)\;\mathrm{d}\mathbf o\right)\;\mathrm{d}\mathbf x\nonumber\\
    \stackrel{(a)}{=} & \sum_{{\boldsymbol\ell}_o}\|M_{\mathfrak{K},{\boldsymbol\ell}_o}\|^2_{L^2(\mathbb{R}^{d_o})}\int_{\mathbb{R}^{d_x}} \left(\sum_{{\boldsymbol\ell}_x}\alpha_{\mathbf v({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)}\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}(\mathbf x)\sqrt{p(\mathbf x)}\right)^2\;\mathrm{d}\mathbf x\nonumber\\
    \stackrel{(b)}{=} & \sum_{{\boldsymbol\ell}_o}\|M_{\mathfrak{K},{\boldsymbol\ell}_o}\|^2_{L^2(\mathbb{R}^{d_o})}\int_{\mathbb{R}^{d_x}} \left(\sum_{{\boldsymbol\ell}_x}\alpha_{\mathbf v({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)}\mathcal{F}\left[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}\sqrt{p}\right](\boldsymbol{\omega}_x)\right)^2\;\mathrm{d}\boldsymbol{\omega}_x\nonumber\\
    =&2^{-\frac{\mathfrak{K}\underline{s}d_o}{s_o}}\|M_{0\boldsymbol{0}}\|^2_{L^2(\mathbb{R}^{d_o})}\int_{\mathbb{R}^{d_x}} \sum_{{\boldsymbol\ell}_o}\left(\sum_{{\boldsymbol\ell}_x}\alpha_{\mathbf v({\boldsymbol\ell}_x,{\boldsymbol\ell}_o)}\mathcal{F}\left[\Omega_{\mathfrak{K},{\boldsymbol\ell}_x}\sqrt{p}\right](\boldsymbol{\omega}_x)\right)^2\;\mathrm{d}\boldsymbol{\omega}_x .\label{eq: gen_coeff_prob_l2}
