\begin{align*}
    (\ast) &= \int_{[0,1]^{d_x}} \left( \int_{[0,1]^{d_x}} \tilde{q}\left( \boldsymbol{\omega}_x - \boldsymbol{\omega}_x^{\prime} \right) \;\mathrm{d}\boldsymbol{\omega}_x^{\prime}  \right)^2 \;\mathrm{d}\boldsymbol{\omega}_x \\
    &= \prod_{i=1}^{d_x} \int_{0}^{1} \left( \int_0^1  \tilde{q}_i\left( \boldsymbol{\omega}_{x, i} - \boldsymbol{\omega}_{x, i}^{\prime} \right) \;\mathrm{d}\boldsymbol{\omega}_{x, i}^{\prime}  \right)^2 \;\mathrm{d}\boldsymbol{\omega}_{x, i} \\
    &= \prod_{i=1}^{d_x} \int_{0}^{1} \left( \int_{\boldsymbol{\omega}_{x, i}-1}^{\boldsymbol{\omega}_{x, i}} \tilde{q}_i\left( \boldsymbol{\omega}_{x, i}^{\prime\prime} \right) \;\mathrm{d}\boldsymbol{\omega}_{x, i}^{\prime\prime}  \right)^2 \;\mathrm{d}\boldsymbol{\omega}_{x, i} \\
    &= \prod_{i=1}^{d_x} \int_{0}^{1} \left( \int_{\boldsymbol{\omega}_{x, i}-1}^{\boldsymbol{\omega}_{x, i}} q_i\left( \boldsymbol{\omega}_{x, i}^{\prime\prime} \right) \;\mathrm{d}\boldsymbol{\omega}_{x, i}^{\prime\prime}  \right)^2 \;\mathrm{d}\boldsymbol{\omega}_{x, i}.
