\begin{align}
    \|q - \Tilde{q}\|_{L^1(\mathbb{R}^{d_x})} &= \int_{\mathbb{R}^{d_x}} \left|q(\boldsymbol{\omega}_x) - \Tilde{q}(\boldsymbol{\omega}_x)\right| \;\mathrm{d}\boldsymbol{\omega}_x \nonumber\\
    &\stackrel{(i)}{=} 2^{d_x} \prod_{i=1}^{d_x} \int_{\zeta/3}^{\infty} \left|\mathcal{F}[\sqrt{g}](\boldsymbol{\omega}_{x,i}) \right| \;\mathrm{d} \boldsymbol{\omega}_{x,i}\nonumber \\
